template <int N>
struct Factorial {
    static constexpr int value = N * Factorial<N - 1>::value;
};

// Base case stops template recursion
template <>
struct Factorial<0> {
    static constexpr int value = 1;
};

// Computation is forced by compiler template instantiation
constexpr int result_7 = Factorial<7>::value;

// Example of result usage within a template context
template <typename T, int Size>
class CompileTimeArray {
    T data[Size];
};

using Buffer = CompileTimeArray<float, Factorial<5>::value>; // Size 120
// No runtime calculation overhead.
